<?php
namespace Tests\Feature;
use App\Models\{Venue,Owner,User,Booking,BookingPayment,VenueMailAccount,MailNotification,GatewayAccount,CheckoutAttempt};use App\Services\{VenueSettings,BookingEngine};use App\Services\Email\{PaymentEmails,EmailDriver};use App\Services\Payments\PaymentService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;use Tests\TestCase;
class EmailLiveTest extends TestCase {
 use RefreshDatabase;
 private function venue():Venue{$u=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Dueño','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));return Venue::create(['owner_id'=>$u->id,'owner_account_id'=>$o->id,'name'=>'Local correo','slug'=>'mail-'.Str::lower(Str::random(7)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>60,'included_hours'=>8,'weekday_price'=>500000,'weekend_price'=>700000,'holiday_price'=>900000,'extra_hour_price'=>100000,'deposit_value'=>30,'address'=>'Colima','lat'=>19.2,'lng'=>-103.7])]);}
 private function booking(Venue $v){return app(BookingEngine::class)->reserve($v,User::factory()->create()->id,['date'=>now()->addMonth()->format('Y-m-d'),'start'=>12,'hours'=>8,'guests'=>10]);}
 private function mail(Venue $v,string $provider='resend'){return VenueMailAccount::create(['venue_id'=>$v->id,'provider'=>$provider,'enabled'=>true,'from_email'=>'reservas@example.com','from_name'=>'Negocio','credentials'=>['api_key'=>'test-secret']]);}
 private function pay(Venue $v,Booking $b){return $this->actingAs($v->owner)->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments',['amount'=>$b->deposit,'method'=>'cash','idempotency_key'=>(string)Str::uuid()])->assertOk();}
 public function test_mail_credentials_are_encrypted_and_never_exposed():void{$v=$this->venue();$a=$this->mail($v);$this->assertStringNotContainsString('test-secret',$a->getRawOriginal('credentials'));$this->actingAs($v->owner)->getJson('/api/owner/venues/'.$v->slug.'/mail')->assertOk()->assertDontSee('test-secret')->assertJsonMissingPath('account.credentials');$this->getJson('/api/venues/'.$v->slug)->assertDontSee('test-secret')->assertJsonMissingPath('mail');}
 public function test_other_owner_cannot_access_mail_or_notification_history():void{$v=$this->venue();$other=$this->venue();$this->actingAs($other->owner)->getJson('/api/owner/venues/'.$v->slug.'/mail')->assertForbidden();$this->getJson('/api/owner/venues/'.$v->slug.'/mail/history')->assertForbidden();}
 public function test_mail_configuration_keeps_secrets_and_requires_new_credentials_when_provider_changes():void{$v=$this->venue();$this->mail($v);$this->actingAs($v->owner);$data=['provider'=>'resend','enabled'=>true,'from_email'=>'reservas@example.com','from_name'=>'Negocio','credentials'=>[]];$this->putJson('/api/owner/venues/'.$v->slug.'/mail',$data)->assertOk();$this->assertSame('test-secret',VenueMailAccount::first()->credentials['api_key']);$data['provider']='postmark';$this->putJson('/api/owner/venues/'.$v->slug.'/mail',$data)->assertUnprocessable();}
 public function test_smtp_internal_hosts_and_header_injection_are_rejected():void{$v=$this->venue();$this->actingAs($v->owner);$data=['provider'=>'smtp','enabled'=>true,'from_email'=>'reservas@example.com','from_name'=>'Negocio','credentials'=>['host'=>'127.0.0.1','port'=>587,'username'=>'test','password'=>'test']];$this->putJson('/api/owner/venues/'.$v->slug.'/mail',$data)->assertUnprocessable();$data['provider']='resend';$data['credentials']=['api_key'=>'test'];$data['from_name']="Name\r\nBcc: attacker@example.com";$this->putJson('/api/owner/venues/'.$v->slug.'/mail',$data)->assertUnprocessable();}
 public function test_pending_booking_does_not_generate_confirmation_mail():void{$v=$this->venue();$this->mail($v);$this->booking($v);$this->assertSame(0,MailNotification::count());Http::fake();app(PaymentEmails::class)->deliver(app(EmailDriver::class));Http::assertNothingSent();}
 public function test_manual_verified_payment_enqueues_once_and_resend_sends_expected_receipt():void{$v=$this->venue();$this->mail($v);$b=$this->booking($v);$this->actingAs($v->owner);$data=['amount'=>$b->deposit,'method'=>'cash','idempotency_key'=>(string)Str::uuid()];$url='/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments';$this->postJson($url,$data)->assertOk();$this->postJson($url,$data)->assertOk();$this->assertSame(1,MailNotification::count());$n=MailNotification::first();$this->assertStringNotContainsString($b->user->email,$n->getRawOriginal('payload'));Http::fake(['api.resend.com/emails'=>Http::response(['id'=>'mail-id'])]);$service=app(PaymentEmails::class);$this->assertSame(1,$service->deliver(app(EmailDriver::class)));$this->assertSame(0,$service->deliver(app(EmailDriver::class)));Http::assertSentCount(1);Http::assertSent(fn($r)=>$r['to'][0]===$b->user->email&&str_contains($r['html'],'reserva está confirmada')&&str_contains($r['html'],$b->order_number)&&str_contains($r['html'],'Saldo restante')&&$r->hasHeader('Idempotency-Key','reservation-payment/'.$n->id));$this->assertSame('sent',$n->fresh()->status);}
 public function test_verified_online_payment_enqueues_but_duplicate_webhook_does_not_repeat():void{$v=$this->venue();$b=$this->booking($v);$g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'mercadopago','enabled'=>true,'sandbox'=>true,'credentials'=>['merchant_id'=>'123']]);$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'mercadopago','amount'=>$b->deposit,'currency'=>'MXN','status'=>'pending','expires_at'=>now()->addMinutes(15)]);$result=['reference'=>$a->id,'amount'=>$a->amount,'currency'=>'MXN','merchant'=>'123','paid'=>true,'transaction'=>'transaction-1','external_id'=>'remote-1','refunded'=>0];app(PaymentService::class)->settle($g,$result);app(PaymentService::class)->settle($g,$result);$this->assertSame(1,MailNotification::count());$this->assertSame('confirmed',$b->fresh()->status);}
 public function test_missing_mail_provider_blocks_outbox_and_enabling_it_delivers_later():void{$v=$this->venue();$b=$this->booking($v);$this->pay($v,$b);$service=app(PaymentEmails::class);$this->assertSame(0,$service->deliver(app(EmailDriver::class)));$this->assertSame('blocked',MailNotification::first()->status);$this->mail($v);Http::fake(['api.resend.com/*'=>Http::response(['id'=>'test'])]);$this->assertSame(1,$service->deliver(app(EmailDriver::class)));}
 public function test_cancellation_after_payment_prevents_a_false_confirmation():void{$v=$this->venue();$this->mail($v);$b=$this->booking($v);$this->pay($v,$b);$b->update(['status'=>'cancelled']);Http::fake();app(PaymentEmails::class)->deliver(app(EmailDriver::class));Http::assertNothingSent();$this->assertSame('needs_review',MailNotification::first()->status);}
 public function test_uncertain_mail_send_is_not_automatically_retried():void{$v=$this->venue();$this->mail($v);$b=$this->booking($v);$this->pay($v,$b);Http::fake(['api.resend.com/*'=>Http::response([],500)]);$service=app(PaymentEmails::class);$service->deliver(app(EmailDriver::class));$service->deliver(app(EmailDriver::class));Http::assertSentCount(1);$n=MailNotification::first();$this->assertSame('unknown',$n->status);$this->assertSame('confirmed',$b->fresh()->status);$this->assertSame($b->deposit,$b->fresh()->paid_total);$this->postJson('/api/owner/venues/'.$v->slug.'/mail/retry/'.$n->id)->assertUnprocessable();}
 public function test_postmark_uses_its_own_adapter_and_reports_acceptance():void{$v=$this->venue();$this->mail($v,'postmark');$b=$this->booking($v);$this->pay($v,$b);Http::fake(['api.postmarkapp.com/email'=>Http::response(['ErrorCode'=>0,'MessageID'=>'postmark-id'])]);$this->assertSame(1,app(PaymentEmails::class)->deliver(app(EmailDriver::class)));Http::assertSent(fn($r)=>$r->hasHeader('X-Postmark-Server-Token','test-secret')&&$r['To']===$b->user->email);}
 public function test_rejected_mail_can_be_requeued_only_by_its_owner():void{$v=$this->venue();$this->mail($v);$b=$this->booking($v);$this->pay($v,$b);Http::fake(['api.resend.com/*'=>Http::response([],422)]);app(PaymentEmails::class)->deliver(app(EmailDriver::class));$n=MailNotification::first();$this->assertSame('failed',$n->status);$this->postJson('/api/owner/venues/'.$v->slug.'/mail/retry/'.$n->id)->assertOk();$this->assertSame('pending',$n->fresh()->status);}
 public function test_public_revisions_change_for_prices_photos_and_publication():void{$v=$this->venue();$first=$this->getJson('/api/venues/'.$v->slug)->assertOk();$etag=$first->headers->get('ETag');$this->getJson('/api/venues/'.$v->slug,['If-None-Match'=>$etag])->assertStatus(304);$settings=$v->settings;$settings['weekday_price']+=100;$v->update(['settings'=>$settings]);$next=$this->getJson('/api/venues/'.$v->slug,['If-None-Match'=>$etag])->assertOk();$this->assertNotSame($first->json('revision'),$next->json('revision'));$v->photos()->create(['source'=>'instagram','url'=>'https://scontent.cdninstagram.com/photo.jpg','visible'=>true]);$this->assertNotSame($next->json('revision'),$this->getJson('/api/venues/'.$v->slug)->json('revision'));$v->update(['published'=>false]);$this->getJson('/api/venues/'.$v->slug)->assertNotFound();$this->getJson('/api/venues')->assertJsonCount(0);}
 public function test_csp_nonce_matches_trusted_script_and_referrer_policy_allows_map_origin():void{$r=$this->get('/');$r->assertHeader('Referrer-Policy','strict-origin-when-cross-origin');preg_match("/nonce-([^']+)/",$r->headers->get('Content-Security-Policy'),$m);$this->assertNotEmpty($m[1]);$this->assertStringContainsString('nonce="'.$m[1].'"',$r->getContent());$this->assertStringNotContainsString("script-src 'self' 'unsafe-inline'",$r->headers->get('Content-Security-Policy'));}
 public function test_smtp_adapter_builds_an_isolated_tls_mailer_without_real_connection():void{$v=$this->venue();$a=VenueMailAccount::create(['venue_id'=>$v->id,'provider'=>'smtp','enabled'=>true,'from_email'=>'reservas@example.com','from_name'=>'Negocio','credentials'=>['host'=>'smtp.resend.com','port'=>587,'username'=>'test','password'=>'test']]);$b=$this->booking($v);$this->pay($v,$b);$sent=\Mockery::mock(\Illuminate\Mail\SentMessage::class);$sent->shouldReceive('getMessageId')->once()->andReturn('smtp-test-id');$mailer=\Mockery::mock(\Illuminate\Mail\Mailer::class);$mailer->shouldReceive('html')->once()->with(\Mockery::type('string'),\Mockery::on(function($callback)use($b){$message=new \Illuminate\Mail\Message(new \Symfony\Component\Mime\Email());$callback($message);$this->assertSame($b->user->email,$message->getSymfonyMessage()->getTo()[0]->getAddress());return true;}))->andReturn($sent);$manager=\Mockery::mock(\Illuminate\Mail\MailManager::class);$manager->shouldReceive('build')->once()->with(\Mockery::on(fn($config)=>$config['host']==='smtp.resend.com'&&$config['port']===587&&$config['require_tls']===true))->andReturn($mailer);$this->app->instance(\Illuminate\Mail\MailManager::class,$manager);$this->assertSame(1,app(PaymentEmails::class)->deliver(app(EmailDriver::class)));}
 public function test_refunded_or_reviewed_online_payment_does_not_send_false_confirmation():void{$v=$this->venue();$b=$this->booking($v);$g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'mercadopago','enabled'=>true,'sandbox'=>true,'credentials'=>['merchant_id'=>'123']]);$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'mercadopago','amount'=>$b->deposit,'currency'=>'MXN','status'=>'pending','expires_at'=>now()->addMinutes(15)]);app(PaymentService::class)->settle($g,['reference'=>$a->id,'amount'=>$a->amount,'currency'=>'MXN','merchant'=>'123','paid'=>true,'transaction'=>'refunded-1','external_id'=>'remote-1','refunded'=>$a->amount]);$this->assertSame(0,MailNotification::count());$this->assertNotNull($b->fresh()->payment_attention);}

 public function test_paid_confirmation_uses_saved_local_design_and_keeps_queued_content():void{
  $v=$this->venue();\App\Models\EmailDesign::create(['scope'=>'venue:'.$v->id,'settings'=>['primary'=>'#223344','templates'=>['confirmation'=>['subject'=>'Tu evento · {{orden}}','title'=>'Nos vemos pronto, {{cliente}}.']]]]);
  $b=$this->booking($v);$b->update(['quote'=>array_merge($b->quote,['reservation_policy'=>\App\Services\ReservationPolicy::acceptance()])]);$this->pay($v,$b);$n=MailNotification::firstOrFail();$p=$n->payload;
  $this->assertSame('Tu evento · '.$b->order_number,$p['subject']);$this->assertStringContainsString('Nos vemos pronto, '.$b->user->name.'.',$p['html']);$this->assertStringContainsString('#223344',$p['html']);$this->assertStringContainsString('Política de cancelación',$p['html']);$this->assertStringContainsString('Saldo restante',$p['html']);$this->assertSame($b->user->email,$p['to']);
  \App\Models\EmailDesign::where('scope','venue:'.$v->id)->update(['settings'=>json_encode(['primary'=>'#112233'])]);$this->assertSame($p,$n->fresh()->payload);
 }
}
